/**
 * Lazily-initialized PostgreSQL connection pool on `pg`.
 *
 * On Workers the connection string is Hyperdrive's local proxy (plaintext
 * localhost — TLS terminates inside Cloudflare's Hyperdrive, the ONLY pipe
 * that can reach Supabase from workerd: node:tls shims are broken there and
 * cloudflare:sockets startTls rejects the pooler certificate chain), so no
 * ssl option is passed there. In real Node connecting directly, the Supabase
 * cert chain is not publicly verifiable, so pass the lenient ssl object.
 */
const IS_CLOUDFLARE_WORKERS =
  typeof navigator !== 'undefined' && /Cloudflare-Workers/i.test(navigator.userAgent ?? '');

let pool: Pool | null = null;
let workersConnectionString: string | null = null;

export function initPool(connectionString: string): void {
  // Workers forbids a socket opened by one request being used by another. A
  // module-scoped Pool hands request B the idle client request A opened; B's
  // I/O on it hangs until the acquire/probe timeout and the client is never
  // freed, so the pool drains to fully stuck (/health 200/503 alternation that
  // decays to all-503). Hyperdrive already pools at the edge — connect per query.
  if (IS_CLOUDFLARE_WORKERS) {
    workersConnectionString = connectionString;
    return;
  }
  if (pool) return;
  // max: 5, not 10 -- Cloudflare Workers hard-caps a single invocation to 6
  // concurrent connections total. A pool sized above that cap doesn't error
  // cleanly — it queues past the limit and connection-acquire calls silently
  // time out, which upstream code that does `catch { return null }` then
  // reports as "not found" even when the row genuinely exists.
  pool = new Pool({
    connectionString,
    max: 5,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: 5_000,
    // No sslmode=... in the connection string either: this repo's pg parses
    // sslmode=require as verify-full and lets it override this option.
    ...(IS_CLOUDFLARE_WORKERS ? {} : { ssl: { rejectUnauthorized: false } }),
  });
  pool.on('error', (err) => {
    logger.error({ err }, 'Unexpected error on idle pg client');
  });
}

/**
 * D1 binding for backend-only cache tables (currently just
 * paynow_subscriptions) that the plugin never touches. Unlike the Postgres
 * pool, this is just a reference to the binding Cloudflare hands us per
 * request — no connection setup, no pool-size limit to exceed.
 */
let d1: D1Database | null = null;

export function initD1(db: D1Database): void {
  d1 = db;
}

export function getD1(): D1Database {
  if (!d1) {
    throw new Error('D1 binding not initialized — initD1() must run before any cache-table query');
  }
  return d1;
}

function getPool(): Pool {
  if (!pool) {
    throw new Error('Postgres pool not initialized — initPool() must run before any query');
  }
  return pool;
}

/** Drains the pool on graceful shutdown (Node dev entrypoint only — Workers has no shutdown hook). */
export async function closePool(): Promise<void> {
  if (pool) await pool.end();
}

// No module-level concurrency counter: a request cancelled mid-query may never
// reach `finally`, leaking the slot for the isolate's lifetime. workerd itself
// queues sockets past its per-invocation cap.
async function workerQuery<T extends QueryResultRow>(
  connectionString: string,
  text: string,
  params: ReadonlyArray<unknown>,
): Promise<QueryResult<T>> {
  const client = new Client({ connectionString, connectionTimeoutMillis: 5_000 });
  try {
    await client.connect();
    return await client.query<T>(text, params as unknown[]);
  } finally {
    void client.end().catch(() => {});
  }
}

export async function query<T extends QueryResultRow>(
  text: string,
  params: ReadonlyArray<unknown>,
): Promise<QueryResult<T>> {
  if (workersConnectionString !== null) {
    return workerQuery<T>(workersConnectionString, text, params);
  }
  const client = await getPool().connect();
  try {
    return await client.query<T>(text, params as unknown[]);
  } finally {
    client.release();
  }
}

/**
 * SELF-SCOPED query: sets the `imperium.uuid` session context for the
 * duration of one statement so the Supabase ROW LEVEL SECURITY policies
 * (player_self on web_dashboard_prefs / discord_links / support_tickets /
 * web_events / web_queue) can restrict rows to exactly this player —
 * defense-in-depth behind the route's own WHERE clause. Policies were
 * verified live (2026-09-13): a connection without the setting sees 0 rows,
 * a wrong-uuid setting sees 0 rows. The current production role (postgres,
 * via Hyperdrive) bypasses RLS until the owner points a Hyperdrive at the
 * restricted imperium_app role — the code path is identical either way, so
 * flipping the role activates enforcement with no further deploys.
 */
export async function playerQuery<T extends QueryResultRow>(
  uuid: string,
  text: string,
  params: ReadonlyArray<unknown>,
): Promise<QueryResult<T>> {
  if (workersConnectionString !== null) {
    // Workers path: one connection per statement. Set the context first —
    // non-transactional set_config persists for the connection's life, and
    // the connection is discarded after this statement anyway.
    await workerQuery(workersConnectionString, "SELECT set_config('imperium.uuid', $1, false)", [uuid]);
    return workerQuery<T>(workersConnectionString, text, params);
  }
  const client = await getPool().connect();
  try {
    await client.query('BEGIN');
    await client.query("SELECT set_config('imperium.uuid', $1, true)", [uuid]);
    const result = await client.query<T>(text, params as unknown[]);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    try { await client.query('ROLLBACK'); } catch { /* connection already broken */ }
    throw err;
  } finally {
    client.release();
  }
}

/**
 * Look up the Minecraft UUID associated with a Discord account, if linked.
 * This is the identity-resolution step for every Discord login — if it can't
 * run, nobody who signed in with Discord can do anything on the site,
 * including cancel a subscription. Redis (Upstash) is a genuinely separate
 * provider from Postgres (Neon), so caching the mapping there and falling
 * back to it on a Postgres failure means login survives either provider
 * going down alone, not just a Postgres misconfiguration/overload. Links
 * change rarely, so a 24h TTL is refreshed on every successful read anyway.
 */
const DISCORD_UUID_CACHE_TTL_SECONDS = 86_400;

export async function getUuidByDiscordId(discordId: string): Promise<string | null> {
  const cacheKey = `discord_uuid:${discordId}`;
  try {
    const result = await query<Pick<DiscordLinkRow, 'uuid'>>(
      'SELECT uuid FROM discord_links WHERE discord_id = $1',
      [discordId],
    );
    const uuid = result.rows[0]?.uuid ?? null;
    if (uuid) void setCachedJson(cacheKey, uuid, DISCORD_UUID_CACHE_TTL_SECONDS);
    return uuid;
  } catch (err) {
    logger.warn({ err, discordId }, 'Postgres lookup failed for discord_id -> uuid; trying Redis fallback');
    return await getCachedJson<string>(cacheKey);
  }
}

/** Look up the Discord id linked to a Minecraft UUID, if any. */
export async function getDiscordIdByUuid(uuid: string): Promise<string | null> {
  const result = await query<Pick<DiscordLinkRow, 'discord_id'>>(
    'SELECT discord_id FROM discord_links WHERE uuid = $1',
    [uuid],
  );
  return result.rows[0]?.discord_id ?? null;
}

/**
 * Return the Discord id currently linked to a Minecraft UUID, or null if the
 * UUID has no link. Used as the hijack guard before {@link upsertDiscordLink}:
 * callers must reject (409) when a UUID is already bound to a DIFFERENT Discord
 * account, so a confirmation can never silently rebind an existing link.
 */
export async function isAlreadyLinked(uuid: string): Promise<string | null> {
  const result = await query<Pick<DiscordLinkRow, 'discord_id'>>(
    'SELECT discord_id FROM discord_links WHERE uuid = $1',
    [uuid],
  );
  return result.rows[0]?.discord_id ?? null;
}

/**
 * Insert (or upsert) a Discord <-> Minecraft link. Called by the bot.
 *
 * B-C31: returns TRUE when this call INSERTED a fresh row (the account's FIRST
 * link) and FALSE when it updated an existing one (a re-link). That signal is
 * what gates the CONFIRM_DISCORD_LINK reward dispatch in /api/link/confirm —
 * re-confirming the same Discord must not re-trigger the first-link reward.
 * `RETURNING (xmax = 0)` is the standard Postgres inserted-vs-updated idiom:
 * on an INSERT xmax is 0; on ON CONFLICT DO UPDATE it is the updating xact id.
 */
export async function upsertDiscordLink(uuid: string, discordId: string): Promise<boolean> {
  const result = await query<{ inserted: boolean }>(
    `INSERT INTO discord_links (uuid, discord_id, linked_at)
     VALUES ($1, $2, NOW())
     ON CONFLICT (uuid) DO UPDATE
       SET discord_id = EXCLUDED.discord_id,
           linked_at = EXCLUDED.linked_at
     RETURNING (xmax = 0) AS inserted`,
    [uuid, discordId],
  );
  // RETURNING always yields exactly one row on this statement; if a driver
  // quirk ever returned none, fail toward "not a first link" — a missed bonus
  // is recoverable by support, a double-granted 25k Denarius reward is not.
  const inserted = result.rows[0]?.inserted === true;
  // Warm the Redis fallback immediately rather than waiting for the first
  // getUuidByDiscordId read — see its docs for why this cache exists.
  void setCachedJson(`discord_uuid:${discordId}`, uuid, DISCORD_UUID_CACHE_TTL_SECONDS);
  return inserted;
}

/** Remove a Discord <-> Minecraft link by Discord id. Returns true if a row was deleted. */
export async function deleteDiscordLinkByDiscordId(discordId: string): Promise<boolean> {
  const result = await query(
    'DELETE FROM discord_links WHERE discord_id = $1',
    [discordId],
  );
  void deleteCachedJson(`discord_uuid:${discordId}`);
  return (result.rowCount ?? 0) > 0;
}

/** Remove a Discord<->Minecraft link by the MC side — used by the website's
 * own unlink action, where the session is uuid-first regardless of login method. */
export async function deleteDiscordLinkByUuid(uuid: string): Promise<boolean> {
  const result = await query<Pick<DiscordLinkRow, 'discord_id'>>(
    'DELETE FROM discord_links WHERE uuid = $1 RETURNING discord_id',
    [uuid],
  );
  const discordId = result.rows[0]?.discord_id;
  if (discordId) void deleteCachedJson(`discord_uuid:${discordId}`);
  return (result.rowCount ?? 0) > 0;
}

/* --------------------------------------------------------------- PayNow */

/** Look up the PayNow customer id linked to a player, if we've seen them at checkout before. */
export async function getPaynowCustomerId(uuid: string): Promise<string | null> {
  // Try the dedicated table first (works for ALL players, not just Discord-linked ones)
  const standalone = await query<{ customer_id: string }>(
    'SELECT customer_id FROM paynow_customers WHERE uuid = $1',
    [uuid],
  );
  if (standalone.rows[0]?.customer_id) return standalone.rows[0].customer_id;

  // Fall back to the legacy discord_links column (for players who linked Discord)
  const result = await query<Pick<DiscordLinkRow, 'paynow_customer_id'>>(
    'SELECT paynow_customer_id FROM discord_links WHERE uuid = $1',
    [uuid],
  );
  return result.rows[0]?.paynow_customer_id ?? null;
}

/** Persist the PayNow customer id for a player. Uses a dedicated table so it works
 *  for gift recipients who have never linked Discord (no discord_links row exists). */
export async function setPaynowCustomerId(uuid: string, customerId: string): Promise<void> {
  // Upsert into the dedicated table (works for all players)
  await query(
    `INSERT INTO paynow_customers (uuid, customer_id) VALUES ($1, $2)
     ON CONFLICT (uuid) DO UPDATE SET customer_id = EXCLUDED.customer_id`,
    [uuid, customerId],
  ).catch((err: unknown) => {
    // Table might not exist yet on some deployments. MUST log: when this write
    // silently fails the PayNow webhook can never resolve the customer back to
    // a uuid, and every subscription cache update for this player is skipped.
    logger.warn({ err: String(err), uuid }, 'paynow_customers upsert failed — webhook customer resolution will miss');
  });
  // Also update discord_links if a row exists (backward compat)
  await query(
    'UPDATE discord_links SET paynow_customer_id = $2 WHERE uuid = $1',
    [uuid, customerId],
  ).catch((err: unknown) => {
    logger.warn({ err: String(err), uuid }, 'discord_links paynow_customer_id backfill failed');
  });
}

/**
 * Cached view of a player's active donor subscription, kept in sync by the
 * PayNow webhook handler. Used for fast dashboard reads without calling out
 * to PayNow on every page load. Lives in D1, not Postgres -- backend-only,
 * the plugin never touches this table (verified before migrating it off
 * Postgres), so there's no JDBC dependency forcing it to stay there.
 */
export async function getCachedSubscription(uuid: string): Promise<PaynowSubscriptionRow | null> {
  const row = await getD1()
    .prepare('SELECT uuid, subscription_id, product_id, status, updated_at FROM paynow_subscriptions WHERE uuid = ?')
    .bind(uuid)
    .first<PaynowSubscriptionRow>();
  return row ?? null;
}

/**
 * Max age of a cached subscription row before dashboard reads stop trusting it
 * (B-09). Healthy rows refresh at worst monthly (renewal webhooks); a row older
 * than 45 days means events were missed (e.g. a dropped cancel that exhausted
 * its retries) and the cache's answer — possibly a stranded status:'active' —
 * must not be served as fact.
 */
const MAX_SUBSCRIPTION_CACHE_AGE_MS = 45 * 24 * 60 * 60 * 1000;

/**
 * True when a cached subscription row's updated_at is older than
 * MAX_SUBSCRIPTION_CACHE_AGE (or missing/unparseable — untrustworthy is stale).
 * D1 stores updated_at as datetime('now') TEXT ('YYYY-MM-DD HH:MM:SS' UTC);
 * a Date is also accepted because the row type declares one.
 */
export function isSubscriptionCacheStale(
  updatedAt: string | Date | null | undefined,
  now: number = Date.now(),
): boolean {
  if (updatedAt == null) return true;
  const ts =
    updatedAt instanceof Date
      ? updatedAt.getTime()
      : Date.parse(`${updatedAt.slice(0, 19).replace(' ', 'T')}Z`);
  if (Number.isNaN(ts)) return true;
  return now - ts > MAX_SUBSCRIPTION_CACHE_AGE_MS;
}

/** Upsert the cached subscription row for a player (called from the webhook handler). */
export async function upsertCachedSubscription(
  uuid: string,
  subscriptionId: string,
  productId: string,
  status: string,
): Promise<void> {
  await getD1()
    .prepare(
      `INSERT INTO paynow_subscriptions (uuid, subscription_id, product_id, status, updated_at)
       VALUES (?, ?, ?, ?, datetime('now'))
       ON CONFLICT (uuid) DO UPDATE
         SET subscription_id = excluded.subscription_id,
             product_id = excluded.product_id,
             status = excluded.status,
             updated_at = excluded.updated_at`,
    )
    .bind(uuid, subscriptionId, productId, status)
    .run();
}

/** Look up a player's uuid by their PayNow customer id (webhooks carry customer id, not uuid). */
export async function getUuidByPaynowCustomerId(customerId: string): Promise<string | null> {
  // Try the dedicated table first (works for ALL players, not just Discord-linked ones)
  const standalone = await query<{ uuid: string }>(
    'SELECT uuid FROM paynow_customers WHERE customer_id = $1',
    [customerId],
  );
  if (standalone.rows[0]?.uuid) return standalone.rows[0].uuid;

  // Fall back to the legacy discord_links column
  const result = await query<Pick<DiscordLinkRow, 'uuid'>>(
    'SELECT uuid FROM discord_links WHERE paynow_customer_id = $1',
    [customerId],
  );
  return result.rows[0]?.uuid ?? null;
}

/**
 * Fetch the full player profile (rank + prestige + stats) for a single UUID.
 * All JOINs are LEFT JOINs so a partial profile is returned if some tables
 * have no row yet.
 */
export async function getPlayerProfile(uuid: string): Promise<PlayerProfile | null> {
  // Use a UNION-based approach: try player_ranks first, but fall back to a minimal
  // profile if only some tables have data. A player who joined the server has data
  // in player_names + currency_balances even if player_ranks hasn't been synced yet.
  const result = await query<PlayerRankRow & PrestigeDataRow & PlayerStatsRow>(
    `SELECT pr.rank_level, pr.rank_name, pr.rank_progress,
            pd.prestige_level, pd.prestige_points,
            ps.blocks_mined, ps.play_time, ps.pvp_kills, ps.pvp_deaths, ps.pvp_trophies
       FROM player_ranks pr
       LEFT JOIN prestige_data pd ON pr.uuid = pd.uuid
       LEFT JOIN player_stats ps ON pr.uuid = ps.uuid
      WHERE pr.uuid = $1`,
    [uuid],
  );

  const row = result.rows[0];
  if (!row) {
    // No player_ranks row — check if the player exists at all (player_names).
    // If they do, return a minimal profile with default values instead of null.
    const nameResult = await query<{ username: string }>(
      'SELECT username FROM player_names WHERE uuid = $1',
      [uuid],
    );
    if (nameResult.rows.length > 0) {
      return {
        uuid,
        rank: { level: 1, name: 'I', progress: 0 },
        prestige: null,
        stats: null,
      };
    }
    return null;
  }

  // blocks_mined is a raw COUNT, not minor-unit currency; do NOT divide by 100.
  const blocksMined = Number(row.blocks_mined ?? 0);
  const pvpKills = Number(row.pvp_kills ?? 0);
  const pvpDeaths = Number(row.pvp_deaths ?? 0);

  return {
    uuid,
    rank: {
      level: Number(row.rank_level ?? 0),
      name: row.rank_name ?? 'Unranked',
      progress: Number(row.rank_progress ?? 0),
    },
    prestige:
      row.prestige_level === null && row.prestige_points === null
        ? null
        : {
            level: Number(row.prestige_level ?? 0),
            points: Number(row.prestige_points ?? 0),
          },
    stats:
      row.blocks_mined === null && row.play_time === null
        ? null
        : {
            blocksMined,
            playTime: row.play_time ?? '0',
            pvpKills,
            pvpDeaths,
            pvpTrophies: Number(row.pvp_trophies ?? 0),
            kdRatio: pvpDeaths === 0 ? (pvpKills > 0 ? pvpKills : null) : pvpKills / pvpDeaths,
          },
  };
}

/**
 * Resolve a username to its Minecraft UUID. Primary source is the
 * plugin-maintained `player_names` registry (kept current on every join,
 * covers Java + Bedrock). If that misses (player never joined the server),
 * fall back to Mojang's profile API for Java Edition usernames so gifting
 * works before the recipient has logged in. Bedrock players (`.prefix`) have
 * no Mojang equivalent — they must have joined at least once.
 *
 * Resolved Mojang UUIDs are cached into `player_names` so subsequent lookups
 * (checkout, webhook delivery) are instant and don't re-hit Mojang.
 *
 * B-28: `external: false` restricts the call to the REGISTRY ONLY — no
 * outbound Mojang/PlayerDB fetch and no registry write. Low-privilege paths
 * (any linked session calling /player/lookup) get that mode so they can
 * neither enumerate arbitrary Mojang names nor grow the shared registry with
 * attacker-chosen rows; trusted paths (bot token, checkout resolution) keep
 * the full fallback.
 */
export async function getUuidByUsername(
  username: string,
  opts: { external?: boolean; strictPlatform?: boolean } = {},
): Promise<string | null> {
  const external = opts.external !== false;
  if (opts.strictPlatform) {
    // Checkout: the store UI prefixes Bedrock names with '.', so a bare name is
    // Java and a dot-name is Bedrock. The same string can be both a Java name
    // and a Bedrock gamertag, and the registry may hold the gamertag without
    // the dot — pick the row whose platform matches instead of the first row.
    const isBedrockName = username.startsWith('.');
    const rows = await query<{ uuid: string }>(
      'SELECT uuid FROM player_names WHERE LOWER(username) = LOWER($1) OR LOWER(username) = LOWER($2)',
      [username, isBedrockName ? username.slice(1) : username],
    );
    const match = rows.rows.find((r) => isFloodgateUuid(r.uuid) === isBedrockName);
    if (match) return match.uuid;
    if (isBedrockName) return null;
  } else {
    const result = await query<{ uuid: string }>(
      'SELECT uuid FROM player_names WHERE LOWER(username) = LOWER($1)',
      [username],
    );
    if (result.rows[0]?.uuid) return result.rows[0].uuid;
  }

  if (!external) return null;

  // Bedrock/Floodgate usernames start with "." — no Mojang equivalent exists.
  if (username.startsWith('.')) return null;

  // Java Edition: resolve the UUID from Mojang/PlayerDB so gifting works even
  // before the recipient has joined the server. Try Mojang first (authoritative),
  // fall back to PlayerDB (aggressive CDN cache, rarely rate-limited). This only
  // fires on a player_names miss, so call volume is tiny.
  const resolved = await resolveUuidFromMojang(username);
  if (!resolved) return null;

  // Cache into player_names so the plugin's join handler and future lookups
  // find it instantly. ON CONFLICT DO NOTHING — if the player joins later, the
  // plugin's upsert updates the row with the authoritative username casing.
  try {
    await query(
      'INSERT INTO player_names (uuid, username) VALUES ($1, $2) ON CONFLICT (uuid) DO NOTHING',
      [resolved.uuid, resolved.name ?? username],
    );
  } catch {
    // Non-fatal — the UUID is resolved even if the cache write fails.
  }
  return resolved.uuid;
}

/** Floodgate encodes a Bedrock player's XUID in the low 64 bits of an otherwise-zero UUID. */
export function isFloodgateUuid(uuid: string): boolean {
  return /^00000000-0000-0000-/i.test(uuid);
}

/**
 * Resolve a Java Edition username to {uuid, name} via Mojang's profile API,
 * falling back to PlayerDB if Mojang is unreachable or rate-limits. Returns
 * null if the username doesn't exist on either service.
 */
async function resolveUuidFromMojang(
  username: string,
): Promise<{ uuid: string; name: string | null } | null> {
  // --- Mojang (authoritative) ---
  try {
    const res = await mojangFetch(
      `https://api.mojang.com/users/profiles/minecraft/${encodeURIComponent(username)}`,
      { signal: AbortSignal.timeout(4000), headers: { Accept: 'application/json' } },
    );
    if (res.ok) {
      const data = (await res.json()) as { id?: string; name?: string };
      if (data.id) {
        const hex = data.id.replace(/-/g, '');
        if (hex.length === 32) {
          const uuid = `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
          return { uuid, name: data.name ?? null };
        }
      }
    }
  } catch {
    // Mojang unreachable or timed out — try PlayerDB below.
  }

  // --- PlayerDB (CDN-cached mirror, very reliable) ---
  try {
    const res = await fetch(
      `https://playerdb.co/api/player/minecraft/${encodeURIComponent(username)}`,
      { signal: AbortSignal.timeout(4000), headers: { Accept: 'application/json' } },
    );
    if (res.ok) {
      const data = (await res.json()) as {
        code?: string;
        data?: { player?: { id?: string; raw_id?: string; username?: string } };
      };
      if (data.code === 'player.found' && data.data?.player) {
        const p = data.data.player;
        // playerdb returns the dashed id; fall back to raw_id if needed.
        const uuid = p.id ?? formatRawUuid(p.raw_id);
        if (uuid && uuid.length === 36) {
          return { uuid, name: p.username ?? null };
        }
      }
    }
  } catch {
    // Both sources failed — give up.
  }
  return null;
}

function formatRawUuid(hex: string | undefined): string | null {
  if (!hex) return null;
  const h = hex.replace(/-/g, '');
  if (h.length !== 32) return null;
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-${h.slice(12, 16)}-${h.slice(16, 20)}-${h.slice(20)}`;
}

/**
 * Resolve a Minecraft UUID to its current username via the plugin-maintained
 * player_names registry (kept current on every join). Returns null if the UUID
 * is unknown (player never joined, or the registry isn't populated yet).
 */
export async function getNameByUuid(uuid: string): Promise<string | null> {
  const result = await query<{ username: string }>(
    'SELECT username FROM player_names WHERE uuid = $1',
    [uuid],
  );
  return result.rows[0]?.username ?? null;
}

/** Fetch all four currency balances for a UUID. WHOLE-UNIT STORAGE (2026-08-18 /
 *  plugin migration V28): every currency is stored in WHOLE units — no ÷100 anywhere. */
export async function getPlayerBalances(
  uuid: string,
): Promise<Record<keyof typeof CURRENCY_COLUMNS, number>> {
  const result = await query<CurrencyBalanceRow>(
    'SELECT currency, balance FROM currency_balances WHERE uuid = $1',
    [uuid],
  );

  const balances: Record<keyof typeof CURRENCY_COLUMNS, number> = {
    denarius: 0,
    tokens: 0,
    beacons: 0,
    goldenCoins: 0,
  };

  // Reverse lookup accepts BOTH canonical and legacy row keys (see CURRENCY_ALIASES).
  for (const row of result.rows) {
    const key = CURRENCY_ALIASES[row.currency.toLowerCase()];
    if (key) {
      balances[key] = Number(row.balance);
    }
  }

  return balances;
}

/** Fetch raw stats row for a UUID (blocks, pvp, playtime). */
export async function getPlayerStats(uuid: string): Promise<PlayerStatsRow | null> {
  // play_time comes from PlaytimeService's table (player_stats.play_time is dead,
  // never incremented); COALESCE keeps the column shape the profile code expects.
  const result = await query<PlayerStatsRow>(
    `SELECT ps.blocks_mined,
            COALESCE(pl.total_secs, 0) AS play_time,
            ps.pvp_kills, ps.pvp_deaths, ps.pvp_trophies
       FROM player_stats ps
       LEFT JOIN player_playtime pl ON pl.uuid = ps.uuid
      WHERE ps.uuid = $1`,
    [uuid],
  );
  return result.rows[0] ?? null;
}

/** A transaction row with its display value as a number. WHOLE-UNIT STORAGE (2026-08-18):
 *  amounts are stored in WHOLE units; displayAmount is the numeric form of amount. */
export interface DisplayTransaction {
  id: number;
  type: string;
  currency: string;
  amount: string; // raw whole-unit amount from the DB
  displayAmount: number; // numeric display amount (whole units)
  description: string | null;
  createdAt: Date;
}

/** Fetch a page of economy transactions for a UUID, newest first. */
export async function getPlayerTransactions(
  uuid: string,
  page: number,
  pageSize: number,
): Promise<{ rows: DisplayTransaction[]; total: number }> {
  const offset = Math.max(0, (page - 1) * pageSize);
  const dataResult = await query<EconomyTransactionRow>(
    `SELECT id, uuid, type, currency, amount, description, created_at
       FROM economy_transactions
      WHERE uuid = $1
      ORDER BY created_at DESC
      LIMIT $2 OFFSET $3`,
    [uuid, pageSize, offset],
  );

  const countResult = await query<{ count: string }>(
    'SELECT COUNT(*)::text AS count FROM economy_transactions WHERE uuid = $1',
    [uuid],
  );
  const total = Number(countResult.rows[0]?.count ?? 0);

  return {
    rows: dataResult.rows.map((row) => ({
      id: row.id,
      type: row.type,
      currency: row.currency,
      amount: row.amount,
      displayAmount: minorUnitsToDisplay(row.amount),
      description: row.description,
      createdAt: row.created_at,
    })),
    total,
  };
}

/** Top 20 players by the requested ranking type. */
export async function getLeaderboard(
  type: 'denarius' | 'blocks' | 'prestige' | 'playtime',
  limit = 20,
): Promise<
  Array<{
    uuid: string;
    name?: string;
    value: number;
    secondary?: number;
  }>
> {
  const cap = Math.min(Math.max(limit, 1), 100);

  // GAME MYSQL FIRST (hybrid, 2026-08-22): real-time from the live game DB.
  // Falls through to the Postgres path below when the game pool isn't
  // initialized or returns empty.
  try {
    const { gameQuery } = await import('./gameMysql.js');
    if (type === 'denarius') {
      const rows = await gameQuery<{ uuid: string; balance: string; username: string | null }>(
        'SELECT cb.uuid, cb.balance, pn.username FROM currency_balances cb LEFT JOIN player_names pn ON cb.uuid = pn.uuid WHERE cb.currency = ? ORDER BY CAST(cb.balance AS UNSIGNED) DESC LIMIT ?',
        [CURRENCY_COLUMNS.denarius, cap],
      );
      if (rows.length > 0) {
        return rows.map((row) => ({
          uuid: row.uuid,
          name: row.username ?? undefined,
          value: minorUnitsToDisplay(row.balance),
        }));
      }
    }
    if (type === 'blocks') {
      const rows = await gameQuery<{ uuid: string; blocks_mined: string; username: string | null }>(
        'SELECT ps.uuid, ps.blocks_mined, pn.username FROM player_stats ps LEFT JOIN player_names pn ON ps.uuid = pn.uuid ORDER BY ps.blocks_mined DESC LIMIT ?',
        [cap],
      );
      if (rows.length > 0) {
        return rows.map((row) => ({
          uuid: row.uuid,
          name: row.username ?? undefined,
          value: Number(row.blocks_mined ?? 0),
        }));
      }
    }
    if (type === 'prestige') {
      const rows = await gameQuery<{ uuid: string; prestige_level: string; prestige_points: string; username: string | null }>(
        'SELECT pd.uuid, pd.prestige_level, pd.prestige_points, pn.username FROM prestige_data pd LEFT JOIN player_names pn ON pd.uuid = pn.uuid ORDER BY pd.prestige_level DESC, pd.prestige_points DESC LIMIT ?',
        [cap],
      );
      if (rows.length > 0) {
        return rows.map((row) => ({
          uuid: row.uuid,
          name: row.username ?? undefined,
          value: Number(row.prestige_level),
          secondary: Number(row.prestige_points),
        }));
      }
    }
    if (type === 'playtime') {
      // player_playtime.total_secs — the PlaytimeService table (created in the game DB
      // via SchemaBuilder; flushed every 60s). player_stats.play_time is a legacy column
      // nobody populates (live check: all zeros) — do NOT use it.
      const rows = await gameQuery<{ uuid: string; total_secs: string | number; username: string | null }>(
        'SELECT pl.uuid, pl.total_secs, pn.username FROM player_playtime pl LEFT JOIN player_names pn ON pl.uuid = pn.uuid ORDER BY pl.total_secs DESC LIMIT ?',
        [cap],
      );
      if (rows.length > 0) {
        return rows.map((row) => ({
          uuid: row.uuid,
          name: row.username ?? undefined,
          value: Number(row.total_secs ?? 0),
        }));
      }
    }
  } catch (err) {
    // B-11: gameQuery now throws GameMySqlUnavailableError instead of
    // swallowing the outage into [] — this fallback actually engages. Distinct
    // tag so a game-MySQL outage is greppable apart from the Postgres errors
    // that follow it.
    logger.warn({ err: String(err), type }, '[game-mysql] leaderboard read failed — Postgres mirror answering');
  }

  if (type === 'denarius') {
    const result = await query<{ uuid: string; balance: string; name: string | null }>(
      `SELECT cb.uuid, cb.balance, pn.username AS name
         FROM currency_balances cb
         LEFT JOIN player_names pn ON cb.uuid = pn.uuid
        WHERE cb.currency = $1
        ORDER BY cb.balance DESC
        LIMIT $2`,
      [CURRENCY_COLUMNS.denarius, cap],
    );
    return result.rows.map((row) => ({
      uuid: row.uuid,
      name: row.name ?? undefined,
      value: minorUnitsToDisplay(row.balance),
    }));
  }

  if (type === 'blocks') {
    const result = await query<{ uuid: string; blocks_mined: string; name: string | null }>(
      `SELECT ps.uuid, ps.blocks_mined, pn.username AS name
         FROM player_stats ps
         LEFT JOIN player_names pn ON ps.uuid = pn.uuid
        ORDER BY ps.blocks_mined DESC
        LIMIT $1`,
      [cap],
    );
    return result.rows.map((row) => ({
      uuid: row.uuid,
      name: row.name ?? undefined,
      value: Number(row.blocks_mined ?? 0),
    }));
  }

  if (type === 'playtime') {
    // player_stats.play_time is dead (never incremented); PlaytimeService tracks
    // real playtime in its own player_playtime table.
    const result = await query<{ uuid: string; play_time: string; name: string | null }>(
      `SELECT pl.uuid, pl.total_secs AS play_time, pn.username AS name
         FROM player_playtime pl
         LEFT JOIN player_names pn ON pl.uuid = pn.uuid
        ORDER BY pl.total_secs DESC
        LIMIT $1`,
      [cap],
    );
    return result.rows.map((row) => ({
      uuid: row.uuid,
      name: row.name ?? undefined,
      value: Number(row.play_time),
    }));
  }

  // prestige
  const result = await query<{ uuid: string; prestige_level: string; prestige_points: string; name: string | null }>(
    `SELECT pd.uuid, pd.prestige_level, pd.prestige_points, pn.username AS name
       FROM prestige_data pd
       LEFT JOIN player_names pn ON pd.uuid = pn.uuid
      ORDER BY pd.prestige_level DESC, pd.prestige_points DESC
      LIMIT $1`,
    [cap],
  );
  return result.rows.map((row) => ({
    uuid: row.uuid,
    name: row.name ?? undefined,
    value: Number(row.prestige_level),
    secondary: Number(row.prestige_points),
  }));
}

