import crypto from 'node:crypto';
import {
  busKvPut, busKvGet, busKvDel, busKvConsume, busKvPutOnce,
  busSendCommand, busWaitForResponse,
} from './busMysql.js';
import type { CommandEnvelope, ResponseEnvelope } from '../types/index.js';
import { nanoid } from 'nanoid';
import { env } from '../env.js';
import { logger } from '../utils/logger.js';
import { redisCommand, redisCommandRetry, redisSubscribeOnce, type RedisSocketConfig } from './redisSocket.js';

/** BUS_TRANSPORT=mysql (default since 2026-09-19) routes every operation in this
 * module to the game-MySQL bus tables; 'redis' restores the old transport verbatim
 * (rollback path while the free-tier sleep policy settles). */
const usePgBus = (): boolean => (process.env.BUS_TRANSPORT ?? 'postgres') !== 'redis';

/** Redis channel used to push commands from the web panel to the plugin. */
function safeEqualHex(a: string, b: string): boolean {
  try {
    return crypto.timingSafeEqual(Buffer.from(a), Buffer.from(b));
  } catch {
    return false;
  }
}

export const COMMANDS_CHANNEL = 'ImperiumMC:commands';
/** Redis channel the plugin uses to push responses back to the web panel. */
export const RESPONSES_CHANNEL = 'ImperiumMC:responses';
/** Redis key prefix for online-player-count style live state. */
export const ONLINE_COUNT_KEY = 'ImperiumMC:online_count';
/** Redis key prefix for link codes (link:initiate). */
export const LINK_CODE_PREFIX = 'ImperiumMC:link_code:';
/**
 * Redis key prefix for in-game website-login codes. Written directly by the
 * plugin's `/webcode` command (same Redis instance, shared credentials) —
 * the backend only ever reads/consumes these, never generates them.
 */
export const LOGIN_CODE_PREFIX = 'ImperiumMC:login_code:';
/**
 * Redis key prefix for one-time OAuth session handoff codes. After the backend
 * completes Discord OAuth it stores the resolved Discord identity here under a
 * random code, then redirects the browser to the frontend with that code; the
 * frontend exchanges it (POST /api/auth/exchange) for its own session cookie.
 * Short TTL (60s) + single-use (GET+DEL) — see createSessionCode/consumeSessionCode.
 */
export const SESSION_CODE_PREFIX = 'ImperiumMC:session:';
/**
 * Redis key prefix for Imperium Client sign-in challenges (issue #2). The
 * backend mints a random Mojang-style serverId under this prefix (60s TTL,
 * single-use via GETDEL); the client joins Mojang's session server with it and
 * proves ownership at /api/client/auth/verify, which consumes it.
 */
export const CLIENT_AUTH_CHALLENGE_PREFIX = 'ImperiumMC:client_auth:';
/**
 * Redis key prefix for short-TTL response caches on hot, read-heavy backend
 * routes (currently /api/player/profile). Postgres compute-hours are the
 * tighter free-tier constraint than Upstash's request count, so caching a
 * repeated identical read here for a few seconds trades a cheap Redis GET for
 * an entire Postgres round trip on every cache hit.
 */
export const RESPONSE_CACHE_PREFIX = 'ImperiumMC:cache:';

/**
 * A hung `cloudflare:sockets` connection (no response ever, not even an
 * error) doesn't throw — it just never resolves. try/catch alone doesn't
 * protect against that, and Cloudflare's own platform watchdog killing the
 * whole invocation is a much worse failure mode than "this cache call gave
 * up quickly." Every response-cache call is raced against this so a stuck
 * Redis connection can never hang a real user-facing request — this is
 * exactly what caused a live incident: concurrent dashboard requests (the
 * same page fires 3 of these in parallel) sent enough simultaneous Redis
 * connections that some hung indefinitely with no timeout, and the whole
 * request died instead of falling through to Postgres as designed.
 */
async function withTimeout<T>(promise: Promise<T>, ms: number, fallback: T): Promise<T> {
  // Mark the raced promise's rejection as handled: when the timeout wins the race and the
  // loser rejects later (socket.closed), that late rejection would otherwise be unhandled —
  // the exact 1101 isolate-crash class from the 2026-08-25 outage. Attaching a no-op catch
  // here covers every caller at once; the race result is unaffected.
  promise.catch(() => {});
  return Promise.race([
    promise,
    new Promise<T>((resolve) => setTimeout(() => resolve(fallback), ms)),
  ]);
}

const CACHE_CALL_TIMEOUT_MS = 1_200;

/**
 * Read a small JSON value from the response cache. Never throws, never hangs
 * — a cache miss, a cache failure, and a cache timeout all look identical to
 * the caller (all mean "go do the real read"), which is exactly the
 * fail-open behavior wanted here.
 */
export async function getCachedJson<T>(key: string): Promise<T | null> {
  if (usePgBus()) {
    const raw = await busKvGet(`${RESPONSE_CACHE_PREFIX}${key}`).catch(() => null);
    if (raw === null) return null;
    try { return JSON.parse(raw) as T; } catch { return null; }
  }
  return withTimeout(
    (async () => {
      try {
        const raw = await redisCommand(socketConfig(), ['GET', `${RESPONSE_CACHE_PREFIX}${key}`]);
        if (raw === null || typeof raw !== 'string') return null;
        return JSON.parse(raw) as T;
      } catch {
        return null;
      }
    })(),
    CACHE_CALL_TIMEOUT_MS,
    null,
  );
}

/** Best-effort cache invalidation — failures/hangs are logged, never thrown or blocking. */
export async function deleteCachedJson(key: string): Promise<void> {
  if (usePgBus()) { await busKvDel(`${RESPONSE_CACHE_PREFIX}${key}`).catch(() => undefined); return; }
  await withTimeout(
    redisCommand(socketConfig(), ['DEL', `${RESPONSE_CACHE_PREFIX}${key}`]).catch((err: unknown) => {
      logger.warn({ err, key }, 'Response cache delete failed — non-fatal');
    }),
    CACHE_CALL_TIMEOUT_MS,
    undefined,
  );
}

/** Best-effort write to the response cache — failures/hangs are logged, never thrown or blocking. */
export async function setCachedJson(key: string, value: unknown, ttlSeconds: number): Promise<void> {
  if (usePgBus()) { await busKvPut(`${RESPONSE_CACHE_PREFIX}${key}`, JSON.stringify(value), ttlSeconds).catch(() => undefined); return; }
  await withTimeout(
    redisCommand(socketConfig(), [
      'SETEX',
      `${RESPONSE_CACHE_PREFIX}${key}`,
      String(ttlSeconds),
      JSON.stringify(value),
    ]).then(
      () => undefined,
      (err: unknown) => {
        logger.warn({ err, key }, 'Response cache write failed — non-fatal');
      },
    ),
    CACHE_CALL_TIMEOUT_MS,
    undefined,
  );
}

function socketConfig(): RedisSocketConfig {
  return {
    host: env.redis.host,
    port: env.redis.port,
    password: env.redis.password || undefined,
    username: env.redis.username || undefined,
    tls: env.redis.tls,
  };
}

/**
 * B-52: atomic single-use consumption. GET-then-DEL is a race — two
 * concurrent consumes of one correct code both GET before either DELs and
 * two sessions walk out of one code. GETDEL (Redis >= 6.2) closes it in one
 * command; if the server rejects the command (older Redis), fall back to
 * the legacy two-step rather than breaking logins.
 */
async function atomicGetDel(key: string): Promise<string | null> {
  try {
    const raw = await redisCommand(socketConfig(), ['GETDEL', key]);
    return typeof raw === 'string' ? raw : null;
  } catch {
    const raw = await redisCommand(socketConfig(), ['GET', key]);
    if (raw === null || typeof raw !== 'string') return null;
    await redisCommand(socketConfig(), ['DEL', key]);
    return raw;
  }
}

/**
 * B-10: claim a nonce exactly once (replay protection). SET NX + EX is
 * atomic — concurrent replays race and exactly one wins. Returns:
 *   true  — claimed (first sighting)
 *   false — already seen within the TTL (replay)
 *   null  — nonce store unavailable; the caller decides (callers that
 *           fail open still have the timestamp window bounding replay)
 */
export async function claimNonceOnce(
  namespace: string,
  nonce: string,
  ttlSeconds: number,
): Promise<boolean | null> {
  if (usePgBus()) {
    try { return await busKvPutOnce(`${namespace}${nonce}`, ttlSeconds); }
    catch { return null; }
  }
  try {
    const res = await redisCommand(socketConfig(), [
      'SET',
      `${namespace}${nonce}`,
      '1',
      'NX',
      'EX',
      String(Math.max(1, Math.floor(ttlSeconds))),
    ]);
    return res === 'OK';
  } catch {
    return null;
  }
}

/**
 * Canonical JSON for signing: recursively key-sorted, compact. Both sides
 * (Node here, Gson in the plugin) must produce byte-identical output.
 */
export function stableStringify(v: unknown): string {
  if (v === null || typeof v !== 'object') return JSON.stringify(v);
  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
  const obj = v as Record<string, unknown>;
  return '{' + Object.keys(obj).sort().map((k) => JSON.stringify(k) + ':' + stableStringify(obj[k])).join(',') + '}';
}

/**
 * HMAC-SHA256 command signature. v2 (2026-08-22 security review): the message
 * is `"$type|$ts|$nonce|$requestId|" + sha256Hex(canonicalJson(envelopeMinusSig))`
 * — the WHOLE body is authenticated. The old v1 envelope-only signature meant
 * one valid DISPATCH_COMMAND signature was valid for EVERY DISPATCH_COMMAND
 * (arbitrary console execution), same for GIVE_ITEM / SET_RAW_CONFIG /
 * WIPE_VAULT / COMPENSATE_PLAYER. The plugin accepts v2 first and v1 only as
 * a one-deploy transition fallback.
 */
export function signCommand(
  type: string,
  timestamp: number,
  nonce: string,
  requestId: string,
  body?: Record<string, unknown>,
): string {
  let message = `${type}|${timestamp}|${nonce}|${requestId}`;
  if (body !== undefined) {
    const bodyHash = crypto.createHash('sha256').update(stableStringify(body)).digest('hex');
    message += `|${bodyHash}`;
  }
  return crypto
    .createHmac('sha256', env.webpanelHmacSecret)
    .update(message)
    .digest('hex');
}

/**
 * Verify an incoming command signature. v2 ONLY (B-53 / P-20 backend half):
 * the v1 envelope-only fallback meant one valid DISPATCH_COMMAND signature
 * was valid for EVERY DISPATCH_COMMAND; the backend sender has been
 * body-bound v2-only since 2026-08-22 and the plugin deletes its v1
 * acceptance in the same window. Callers verified before removal: none in
 * src/ (the plugin side owns the live verification) — this stays as the
 * canonical v2 verifier for the bus protocol.
 */
export function verifyCommand(
  type: string,
  timestamp: number,
  nonce: string,
  requestId: string,
  signature: string,
  body?: Record<string, unknown>,
): boolean {
  const expected = signCommand(type, timestamp, nonce, requestId, body);
  return safeEqualHex(expected, signature);
}

/**
 * Send a command to the plugin via the commands channel. The command envelope
 * is HMAC-signed. Does NOT wait for a response — use sendCommandWithResponse
 * for that.
 */
export async function sendCommand(
  type: string,
  payload: Record<string, unknown>,
): Promise<CommandEnvelope> {
  const requestId = nanoid(16);
  // Unix SECONDS — the plugin verifies a 30s window against seconds and signs
  // the message with the seconds value. Sending milliseconds broke the bus.
  const timestamp = Math.floor(Date.now() / 1000);
  const nonce = crypto.randomBytes(16).toString('hex');
  // v2: the envelope minus `sig` IS the body — sign it whole.
  const bodyForSig: Record<string, unknown> = { type, request_id: requestId, ts: timestamp, nonce, payload };
  const signature = signCommand(type, timestamp, nonce, requestId, bodyForSig);

  const envelope: CommandEnvelope = {
    type,
    request_id: requestId,
    ts: timestamp,
    nonce,
    // Field name MUST be `sig` to match the plugin's `json.get("sig")` read.
    // Sending `signature` was rejected at the plugin's presence guard.
    sig: signature,
    payload,
  };

  if (usePgBus()) {
    await busSendCommand(JSON.stringify(envelope));
    return envelope;
  }
  await redisCommand(socketConfig(), ['PUBLISH', COMMANDS_CHANNEL, JSON.stringify(envelope)]);
  return envelope;
  // 2026-09-19: unreachable in pg mode — the pg branch above returned already; kept for
  // symmetry with the rollback path. (Inserted marker only.)
}

function parseResponse(message: string): ResponseEnvelope | null {
  let parsed: ResponseEnvelope;
  try {
    parsed = JSON.parse(message) as ResponseEnvelope;
  } catch {
    logger.warn({ message }, 'Could not parse response envelope');
    return null;
  }
  // The plugin publishes `status` ("OK"|"ERROR"), not `ok`. Derive `ok` so
  // callers can use the boolean regardless of which envelope shape arrived.
  if (typeof parsed.ok !== 'boolean') {
    parsed.ok = parsed.status === 'OK';
  }
  return parsed;
}

/**
 * Send a command and wait for the matching response on the responses channel.
 * Rejects if no response arrives within timeoutMs.
 *
 * Subscribes first, THEN publishes (via `onSubscribed`) — avoids the race
 * where the plugin could respond before we're listening. Each call owns its
 * own subscribe connection scoped to this one request/response pair, rather
 * than a shared long-lived subscriber multiplexing by request_id (that model
 * doesn't fit Workers' per-request execution well).
 */
export async function sendCommandWithResponse(
  type: string,
  payload: Record<string, unknown>,
  timeoutMs = 5_000,
): Promise<ResponseEnvelope> {
  if (usePgBus()) {
    const envelope = await sendCommand(type, payload);
    const message = await busWaitForResponse(envelope.request_id, timeoutMs);
    if (message === null) throw new Error(`Timed out waiting for response to ${type}`);
    const parsed = parseResponse(message);
    if (parsed === null) throw new Error(`Received unparseable response to ${type}`);
    return parsed;
  }
  let requestId = '';
  const message = await redisSubscribeOnce(
    socketConfig(),
    RESPONSES_CHANNEL,
    (raw) => {
      const parsed = parseResponse(raw);
      return parsed !== null && parsed.request_id === requestId;
    },
    timeoutMs,
    async () => {
      const envelope = await sendCommand(type, payload);
      requestId = envelope.request_id;
    },
  );

  if (message === null) {
    throw new Error(`Timed out waiting for response to ${type}`);
  }
  const parsed = parseResponse(message);
  if (parsed === null) {
    throw new Error(`Received unparseable response to ${type}`);
  }
  return parsed;
}

/**
 * Block until a response arrives for the given request_id. Returns null on
 * timeout. Mostly useful when you have an externally-produced request_id.
 */
export async function waitForResponse(
  requestId: string,
  timeoutMs = 5_000,
): Promise<ResponseEnvelope | null> {
  if (usePgBus()) {
    const message = await busWaitForResponse(requestId, timeoutMs);
    return message === null ? null : parseResponse(message);
  }
  const message = await redisSubscribeOnce(
    socketConfig(),
    RESPONSES_CHANNEL,
    (raw) => {
      const parsed = parseResponse(raw);
      return parsed !== null && parsed.request_id === requestId;
    },
    timeoutMs,
  );
  return message === null ? null : parseResponse(message);
}

/** Online player count as published by the plugin, or null if unset. */
export async function getOnlinePlayerCount(): Promise<number | null> {
  if (usePgBus()) {
    const raw = await busKvGet(ONLINE_COUNT_KEY).catch(() => null);
    if (raw === null) return null;
    const parsed = Number.parseInt(raw, 10);
    return Number.isNaN(parsed) ? null : parsed;
  }
  // RETRY (2026-08-25): the status endpoint's #1 data source — one retry absorbs Layerbase's
  // transient TLS accept failures instead of reporting a live server as offline.
  const raw = await redisCommandRetry(socketConfig(), ['GET', ONLINE_COUNT_KEY]);
  if (raw === null || typeof raw !== 'string') return null;
  const parsed = Number.parseInt(raw, 10);
  return Number.isNaN(parsed) ? null : parsed;
}

/** Either half of a pending link, as stored against a link code. */
export interface LinkCodeRecord {
  /** Set when the link was initiated from the web panel (Discord known). */
  discordId?: string;
  /** Set when the link was initiated in-game (Minecraft UUID known). */
  uuid?: string;
  createdAt: number;
}

/**
 * Generate a 6-character alphanumeric link code and store it in Redis.
 * The code carries whichever identity half is already known at initiation
 * time (discordId for the web flow, uuid for the in-game flow); the other
 * half is supplied by the caller of /api/link/confirm.
 */
export async function createLinkCode(
  partial: Pick<LinkCodeRecord, 'discordId'> | Pick<LinkCodeRecord, 'uuid'>,
  ttlSeconds = 600,
): Promise<string> {
  const code = generateLinkCode();
  const record: LinkCodeRecord = { ...partial, createdAt: Date.now() };
  if (usePgBus()) {
    await busKvPut(`${LINK_CODE_PREFIX}${code}`, JSON.stringify(record), ttlSeconds);
    return code;
  }
  await redisCommand(socketConfig(), [
    'SET',
    `${LINK_CODE_PREFIX}${code}`,
    JSON.stringify(record),
    'EX',
    ttlSeconds,
  ]);
  return code;
}

/**
 * Look up and consume (single-use delete) a link code. Returns the stored
 * record, or null if the code was not found / already consumed / expired.
 */
export async function consumeLinkCode(code: string): Promise<LinkCodeRecord | null> {
  const key = `${LINK_CODE_PREFIX}${code.toUpperCase()}`;
  const raw = usePgBus() ? await busKvConsume(key) : await atomicGetDel(key);
  if (raw === null) return null;
  try {
    return JSON.parse(raw) as LinkCodeRecord;
  } catch (err) {
    // The DEL above already burned the single-use code — the player sees
    // "invalid code" for a code they genuinely held. Log the corruption.
    logger.warn({ err: String(err), key }, 'link code record corrupt — code consumed but unusable');
    return null;
  }
}

/**
 * Look up and consume (single-use delete) an in-game website-login code.
 * The plugin stores the record as JSON `{uuid, username, createdAt}` under
 * `ImperiumMC:login_code:<CODE>` with a 900s (15min) TTL. Returns null if the
 * code was not found, already used, or expired.
 */
export async function consumeLoginCode(
  code: string,
): Promise<{ uuid: string; username?: string } | null> {
  const key = `${LOGIN_CODE_PREFIX}${code.trim()}`;
  const raw = usePgBus() ? await busKvConsume(key) : await atomicGetDel(key);
  if (raw === null) return null;
  try {
    const parsed = JSON.parse(raw) as { uuid?: string; username?: string };
    if (!parsed.uuid) return null;
    return { uuid: parsed.uuid, username: parsed.username };
  } catch (err) {
    logger.warn({ err: String(err), key }, 'login code record corrupt — code consumed but unusable');
    return null;
  }
}

const LINK_CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; // no ambiguous chars

function generateLinkCode(length = 6): string {
  let out = '';
  const bytes = crypto.randomBytes(length);
  for (let i = 0; i < length; i++) {
    out += LINK_CODE_ALPHABET[bytes[i]! % LINK_CODE_ALPHABET.length];
  }
  return out;
}

/**
 * The identity the backend resolves during a browser login (Discord OAuth or
 * Microsoft/Minecraft sign-in), handed off to the frontend via a one-time
 * session code so the frontend can sign its own cookie without ever seeing
 * an OAuth secret.
 */
export interface SessionHandoff {
  discordId?: string;
  discordUsername: string | null;
  /** Discord avatar hash (not a URL) — the frontend renders it via discordAvatarUrl(). */
  discordAvatar: string | null;
  /** Microsoft (Minecraft) sign-in: the proven account, dashed-UUID form. */
  mcUuid?: string;
  mcUsername?: string | null;
}

/**
 * Store a Discord identity under a fresh one-time code (TTL 60s) and return the
 * code. The browser is redirected to the frontend with this code; the frontend
 * then consumes it via consumeSessionCode (called by POST /api/auth/exchange).
 */
export async function createSessionCode(
  payload: SessionHandoff,
  ttlSeconds = 60,
): Promise<string> {
  const code = nanoid(24);
  const key = `${SESSION_CODE_PREFIX}${code}`;
  if (usePgBus()) {
    await busKvPut(key, JSON.stringify({ ...payload, createdAt: Date.now() }), ttlSeconds);
    return code;
  }
  await redisCommand(socketConfig(), [
    'SET',
    key,
    JSON.stringify({ ...payload, createdAt: Date.now() }),
    'EX',
    ttlSeconds,
  ]);
  return code;
}

/**
 * Consume (single-use GET+DEL) a session handoff code. Returns the stored
 * Discord identity, or null if the code was missing/expired/already consumed.
 */
export async function consumeSessionCode(code: string): Promise<SessionHandoff | null> {
  const key = `${SESSION_CODE_PREFIX}${code.trim()}`;
  const raw = usePgBus() ? await busKvConsume(key) : await atomicGetDel(key);
  if (raw === null) return null;
  try {
    const parsed = JSON.parse(raw) as Partial<SessionHandoff>;
    // Either identity is enough: a Discord OAuth handoff carries discordId,
    // a Microsoft/Minecraft sign-in carries mcUuid.
    if (!parsed.discordId && !parsed.mcUuid) return null;
    return {
      ...(parsed.discordId ? { discordId: parsed.discordId } : {}),
      discordUsername: parsed.discordUsername ?? null,
      discordAvatar: parsed.discordAvatar ?? null,
      ...(parsed.mcUuid ? { mcUuid: parsed.mcUuid } : {}),
      mcUsername: parsed.mcUsername ?? null,
    };
  } catch (err) {
    logger.warn({ err: String(err), key }, 'session code record corrupt — code consumed but unusable');
    return null;
  }
}

/* ── Issue #2: Imperium Client sign-in challenges ────────────────────────────
 * Same store + consume discipline as the link/login/session codes above. */

/**
 * Mint a fresh client sign-in challenge: 20 random bytes as lowercase hex
 * (the shape Mojang's serverId field accepts), stored single-use for
 * `ttlSeconds` (60 per issue #2). Returns the serverId the client passes to
 * MinecraftSessionService.joinServer.
 */
export async function createClientAuthChallenge(ttlSeconds = 60): Promise<string> {
  const serverId = crypto.randomBytes(20).toString('hex');
  const key = `${CLIENT_AUTH_CHALLENGE_PREFIX}${serverId}`;
  const record = JSON.stringify({ createdAt: Date.now() });
  if (usePgBus()) {
    await busKvPut(key, record, ttlSeconds);
    return serverId;
  }
  await redisCommand(socketConfig(), ['SET', key, record, 'EX', String(ttlSeconds)]);
  return serverId;
}

/**
 * Atomically consume (single-use GETDEL) a client sign-in challenge. Returns
 * the stored record, or null when the serverId was never issued, has expired,
 * or was already consumed (replay). Throws when the store itself is
 * unreachable — callers must distinguish that (503) from a dead challenge
 * (401), unlike the miss path which is an ordinary auth failure.
 */
export async function consumeClientAuthChallenge(
  serverId: string,
): Promise<{ createdAt: number } | null> {
  const key = `${CLIENT_AUTH_CHALLENGE_PREFIX}${serverId}`;
  const raw = usePgBus() ? await busKvConsume(key) : await atomicGetDel(key);
  if (raw === null) return null;
  try {
    const parsed = JSON.parse(raw) as { createdAt?: number };
    return { createdAt: typeof parsed.createdAt === 'number' ? parsed.createdAt : 0 };
  } catch (err) {
    logger.warn({ err: String(err), key }, 'client auth challenge record corrupt — consumed but unusable');
    return null;
  }
}

/* ── Microsoft (Minecraft) website sign-in: PKCE state store ─────────────────
 * The /auth/ms/start hop parks the PKCE verifier under the frontend-generated
 * state; /auth/ms/callback consumes it exactly once (GETDEL semantics — the
 * state is single-use, so a replayed authorize redirect finds nothing). */
const MS_OAUTH_PREFIX = 'ImperiumMC:ms_oauth:';

export async function storeMsOauthState(
  state: string,
  verifier: string,
  ttlSeconds: number,
): Promise<void> {
  if (usePgBus()) {
    await busKvPut(`${MS_OAUTH_PREFIX}${state}`, JSON.stringify({ verifier }), ttlSeconds);
    return;
  }
  await redisCommand(socketConfig(), [
    'SET',
    `${MS_OAUTH_PREFIX}${state}`,
    JSON.stringify({ verifier }),
    'EX',
    ttlSeconds,
  ]);
}

export async function consumeMsOauthState(state: string): Promise<string | null> {
  const raw = usePgBus()
    ? await busKvConsume(`${MS_OAUTH_PREFIX}${state}`)
    : await atomicGetDel(`${MS_OAUTH_PREFIX}${state}`);
  if (raw === null) return null;
  try {
    const parsed = JSON.parse(raw) as { verifier?: string };
    return typeof parsed.verifier === 'string' ? parsed.verifier : null;
  } catch {
    return null;
  }
}
